void Solver::bump_var(int var, double coeff) {
    // Compute increment based on current var_inc and coefficient
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale activities if any exceed a safe upper bound to avoid overflow
    const double ACTIVITY_LIMIT = 1e120;
    if (activity[var] > ACTIVITY_LIMIT) {
        const double SCALE_FACTOR = 1e-120;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE_FACTOR;
        }
        var_inc *= SCALE_FACTOR;
    }

    // Ensure the variable is correctly positioned in the VSIDS heap
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
